#!/usr/bin/env python3
"""Deduplicate attendees.csv by email, keeping the first row per email."""
import csv

INPUT_PATH = "attendees.csv"
OUTPUT_PATH = "attendees_clean.csv"

with open(INPUT_PATH, "r", encoding="utf-8", newline="") as infile:
    reader = csv.reader(infile)
    try:
        header = next(reader)
    except StopIteration:
        raise SystemExit(f"{INPUT_PATH} is empty")

    try:
        email_index = header.index("email")
    except ValueError:
        raise SystemExit("no email column in attendees.csv")

    seen = set()
    with open(OUTPUT_PATH, "w", encoding="utf-8", newline="") as outfile:
        writer = csv.writer(outfile)
        writer.writerow(header)

        for row in reader:
            if not row:
                continue
            # Make sure short rows cannot cause an IndexError.
            if email_index >= len(row):
                continue
            email = row[email_index]
            if email in seen:
                continue
            seen.add(email)
            writer.writerow(row)
